import{_ as e,o as a,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const b=JSON.parse('{"title":"Locator stability rules","description":"Every rule Piwi uses to call a locator your tests use brittle or worth watching, what it catches and why that breaks.","frontmatter":{"title":"Locator stability rules","description":"Every rule Piwi uses to call a locator your tests use brittle or worth watching, what it catches and why that breaks.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/locator-stability.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/locator-stability.html"}],["meta",{"property":"og:title","content":"Locator stability rules | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every rule Piwi uses to call a locator your tests use brittle or worth watching, what it catches and why that breaks."}]]},"headers":[],"relativePath":"reference/locator-stability.md","filePath":"reference/locator-stability.md","lastUpdated":1790836807000}'),d={name:"reference/locator-stability.md"};function s(l,t,c,i,n,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="locator-stability-rules" tabindex="-1">Locator stability rules <a class="header-anchor" href="#locator-stability-rules" aria-label="Permalink to &quot;Locator stability rules&quot;">​</a></h1><p>A <strong>brittle locator</strong> breaks on a change unrelated to what its test checks: a restyle, a wrapper added around an element, an item added to a list, a copy edit, other data. Piwi judges every locator of the <a href="/features/locator-usage.html">locator index</a> with the rules below, from the locator&#39;s text alone, and gives it one of three levels:</p><ul><li><strong>Brittle</strong>: at least one rule gives it that level. The <a href="/features/tested-elements.html#brittle-locators">Tested elements</a> overlay lists it under <strong>At risk</strong>, and offers a replacement.</li><li><strong>Watch</strong>: a rule has something to say, but the locator does not break on its own. Shown on the element&#39;s card and on the Locators page, never listed.</li><li><strong>Stable</strong>: no rule has anything to say.</li></ul><p>A locator takes the level of its worst part: a stable container cannot save a brittle target, and a brittle container breaks every locator searching inside it. Locators nested in <code>filter({ has })</code>, <code>and()</code> and <code>or()</code> count as parts.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Level</th><th>Catches</th><th>Example</th></tr></thead><tbody><tr><td>Position<br><code>position</code></td><td>brittle for <code>nth(1)</code> and beyond; watch for <code>first()</code>, <code>last()</code> and <code>nth(0)</code></td><td>An element picked by its order. An element added above it, or a list sorted another way, moves it.</td><td><code>getByRole(&#39;listitem&#39;).nth(2)</code></td></tr><tr><td>CSS class<br><code>css-class</code></td><td>brittle for a utility, hashed or CSS-in-JS class; watch for a named class</td><td>An element found by a class. Classes change with the styling.</td><td><code>locator(&#39;.bg-blue-500&#39;)</code>, <code>locator(&#39;.css-1q2w3e&#39;)</code></td></tr><tr><td>CSS structure<br><code>css-structure</code></td><td>brittle</td><td>A child or sibling combinator, <code>:nth-child()</code> and its kind, three or more selectors deep, or a descendant chain of tags only. A wrapper added or moved breaks it.</td><td><code>locator(&#39;form &gt; div:nth-child(2) input&#39;)</code></td></tr><tr><td>XPath<br><code>xpath</code></td><td>brittle when absolute or indexed; watch otherwise</td><td>XPath follows the document structure.</td><td><code>locator(&#39;//main/div[2]//button&#39;)</code></td></tr><tr><td>Generated id<br><code>generated-id</code></td><td>brittle</td><td>An id a framework or a build generates, which changes from one render or build to the next.</td><td><code>locator(&#39;#radix-:r4:&#39;)</code>, <code>locator(&#39;#input-1748291&#39;)</code></td></tr><tr><td>Style attribute<br><code>style-attribute</code></td><td>brittle</td><td>The <code>style</code> or <code>class</code> attribute matched as a string, which any styling edit changes.</td><td><code>locator(&#39;[style*=&quot;display: block&quot;]&#39;)</code></td></tr><tr><td>Long text<br><code>long-text</code></td><td>watch</td><td>An exact string over 40 characters in <code>getByText</code>, a <code>name</code> or <code>hasText</code>: copy changes long before behavior does.</td><td>Marketing copy</td></tr><tr><td>Number in text<br><code>data-text</code></td><td>watch</td><td>A count, price, date, time or percentage inside an exact string, which changes with the data.</td><td><code>getByRole(&#39;button&#39;, { name: &#39;Cart (3)&#39; })</code></td></tr><tr><td>Long chain<br><code>deep-chain</code></td><td>watch</td><td>More than three locating calls: each container is one more thing a change can break.</td><td>Four chained <code>getBy…</code> calls</td></tr></tbody></table><p>Not flagged: <code>getByTestId</code>, <code>getByRole</code> with a name, <code>getByLabel</code>, <code>getByPlaceholder</code>, <code>getByAltText</code>, <code>getByTitle</code>, an id that is not generated, <code>[name=…]</code> and <code>[data-testid=…]</code>, a single tag inside a container, a regular expression, and a short text. A locator matching several elements is not a stability problem: the overlay shows it as ambiguous.</p><h2 id="replacements" tabindex="-1">Replacements <a class="header-anchor" href="#replacements" aria-label="Permalink to &quot;Replacements&quot;">​</a></h2><p>On a live page, the overlay offers a replacement for a brittle locator that finds exactly one element. It ranks the locators for that element the way the <a href="/features/extension.html">Piwi Picker extension</a> does, keeps those these rules call stable and that find only that element on the page, and picks one the way <a href="/features/locator-healing.html">locator healing</a> does: the locator&#39;s own method, then its family (role, text, label, test id, CSS), when that is stable enough; otherwise the most stable one. When no stable locator finds only that element, the overlay says to give it a test id.</p><p>A replacement is checked against the page as it is now. A test that uses the locator in another state of the page may need a different one.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/tested-elements.html">Tested elements</a></li><li><a href="/features/locator-usage.html">Who uses a locator</a></li><li><a href="/features/locator-healing.html">Locator healing</a></li></ul>',12)])])}const g=e(d,[["render",s]]);export{b as __pageData,g as default};
